func (o *Order) ValidateForPublish() error {
    if o.qty == 0 { return errors.New("qty required") }
    return nil
}

check := sync.OnceValue(o.ValidateForPublish)   // memoised one-shot gate
if err := check(); err != nil { return err }
return bus.Publish(ctx, o)                       // irreversible step
